<div class="d-flex justify-content-between mb-3"><h4>Gift Cards &amp; Vouchers</h4><?php if (Auth::can('pos.giftcard.sell')): ?><a class="btn btn-primary" href="<?= url('giftcards/issue') ?>"><i class="bi bi-gift"></i> Sell gift card</a><?php endif; ?></div>
<div class="alert alert-light border">Outstanding gift card balances (your liability): <b><?= e(money($liab)) ?></b></div>
<form class="row g-2 mb-3" method="get"><input type="hidden" name="r" value="giftcards/index"><div class="col-md-4"><input class="form-control" name="q" value="<?= e($q) ?>" placeholder="Card code, customer name or phone"></div><div class="col-md-2"><select class="form-select" name="status" data-autosubmit><option value="">All</option><?php foreach (['active', 'used', 'blocked'] as $x): ?><option value="<?= $x ?>" <?= $st === $x ? 'selected' : '' ?>><?= ucfirst($x) ?></option><?php endforeach; ?></select></div><div class="col-auto"><button class="btn btn-outline-secondary"><i class="bi bi-search"></i></button></div></form>
<div class="card"><div class="table-responsive"><table class="table table-sm table-hover mb-0"><thead class="table-light"><tr><th>Code</th><th>Issued</th><th>Customer</th><th class="text-end">Initial</th><th class="text-end">Balance</th><th>Expires</th><th>Status</th></tr></thead><tbody>
<?php foreach ($rows as $r): ?><tr><td><a href="<?= url('giftcards/view', ['id' => $r['id']]) ?>"><?= e($r['code']) ?></a></td><td><?= e(fmt_date($r['issued_at'], 'd M Y')) ?></td><td><?= e($r['customer']) ?></td><td class="text-end"><?= number_format($r['initial_amount'], 2) ?></td><td class="text-end"><?= number_format($r['balance'], 2) ?></td><td><?= e($r['expires_on'] ?: '-') ?></td><td><?= badge($r['status']) ?></td></tr><?php endforeach; ?>
<?php if (!$rows): ?><tr><td colspan="7" class="text-center text-muted py-3">No gift cards.</td></tr><?php endif; ?></tbody></table></div></div>
